import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import Card from '../components/Card';
import Button from '../components/Button';
import api from '../services/api';
import { useTheme } from '../context/ThemeContext';
import { format, parseISO, isAfter, addDays } from 'date-fns';
import { ptBR } from 'date-fns/locale';

function Dashboard() {
  const { theme } = useTheme();
  const [stats, setStats] = useState({ volunteers: 0, ministries: 0, schedules: 0, shifts: 0 });
  const [events, setEvents] = useState([]);
  const [upcoming, setUpcoming] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [volRes, minRes, schRes, shiftsRes] = await Promise.all([
        api.get('/volunteers.php'),
        api.get('/ministries.php'),
        api.get('/schedules.php'),
        api.get('/shifts.php')
      ]);

      setStats({
        volunteers: volRes.data.length,
        ministries: minRes.data.length,
        schedules: schRes.data.length,
        shifts: shiftsRes.data.length
      });

      const now = new Date();
      const upcomingData = schRes.data
        .filter(s => s.status === 'draft' || !s.status)
        .sort((a, b) => new Date(a.date) - new Date(b.date))
        .slice(0, 5);

      setUpcoming(upcomingData);
    } catch (error) {
      console.error('Error loading dashboard:', error);
    } finally {
      setLoading(false);
    }
  };

  const statCards = [
    { label: 'Voluntários', value: stats.volunteers, icon: '👥', color: '#3B82F6', path: '/volunteers' },
    { label: 'Ministérios', value: stats.ministries, icon: '⛪', color: '#8B5CF6', path: '/ministries' },
    { label: 'Turnos', value: stats.shifts, icon: '🕐', color: '#F59E0B', path: '/shifts' },
    { label: 'Escalas', value: stats.schedules, icon: '📅', color: '#10B981', path: '/generate' },
  ];

  const pageStyle = {
    maxWidth: '1200px',
    margin: '0 auto',
  };

  const headerStyle = {
    marginBottom: '24px',
  };

  const titleStyle = {
    fontSize: '28px',
    fontWeight: '700',
    color: theme.text,
    marginBottom: '8px',
  };

  const subtitleStyle = {
    fontSize: '16px',
    color: theme.textSecondary,
  };

  const statsGridStyle = {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
    gap: '16px',
    marginBottom: '24px',
  };

  const statCardStyle = {
    display: 'flex',
    alignItems: 'center',
    gap: '16px',
    cursor: 'pointer',
    transition: 'all 0.2s ease',
  };

  const iconContainerStyle = (color) => ({
    width: '56px',
    height: '56px',
    borderRadius: '14px',
    backgroundColor: color + '20',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: '24px',
  });

  const statInfoStyle = {
    display: 'flex',
    flexDirection: 'column',
  };

  const statLabelStyle = {
    fontSize: '14px',
    color: theme.textSecondary,
  };

  const statValueStyle = {
    fontSize: '28px',
    fontWeight: '700',
    color: theme.text,
  };

  const sectionTitleStyle = {
    fontSize: '20px',
    fontWeight: '600',
    color: theme.text,
    marginBottom: '16px',
  };

  const calendarContainerStyle = {
    backgroundColor: theme.surface,
    borderRadius: '16px',
    padding: '24px',
    boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
    border: `1px solid ${theme.border}`,
  };

  const calendarGridStyle = {
    display: 'grid',
    gridTemplateColumns: 'repeat(7, 1fr)',
    gap: '4px',
  };

  const dayHeaderStyle = {
    textAlign: 'center',
    fontSize: '12px',
    fontWeight: '600',
    color: theme.textSecondary,
    padding: '8px',
  };

  const dayCellStyle = (isToday, hasEvent) => ({
    aspectRatio: '1',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: '8px',
    fontSize: '14px',
    cursor: 'pointer',
    backgroundColor: isToday ? theme.primary + '15' : 'transparent',
    color: isToday ? theme.primary : theme.text,
    fontWeight: isToday ? '600' : '400',
    border: hasEvent ? `2px solid ${theme.primary}` : '2px solid transparent',
    transition: 'all 0.2s ease',
  });

  const upcomingListStyle = {
    display: 'flex',
    flexDirection: 'column',
    gap: '12px',
  };

  const upcomingItemStyle = {
    display: 'flex',
    alignItems: 'center',
    gap: '16px',
    padding: '16px',
    backgroundColor: theme.background,
    borderRadius: '12px',
    borderLeft: `4px solid ${theme.primary}`,
  };

  const dateBoxStyle = {
    minWidth: '70px',
    textAlign: 'center',
  };

  const dayStyle = {
    fontSize: '24px',
    fontWeight: '700',
    color: theme.primary,
  };

  const monthStyle = {
    fontSize: '12px',
    color: theme.textSecondary,
    textTransform: 'uppercase',
  };

  const upcomingInfoStyle = {
    flex: 1,
  };

  const upcomingTitleStyle = {
    fontSize: '16px',
    fontWeight: '600',
    color: theme.text,
  };

  const upcomingMetaStyle = {
    fontSize: '14px',
    color: theme.textSecondary,
    marginTop: '4px',
  };

  const emptyStyle = {
    textAlign: 'center',
    padding: '40px',
    color: theme.textSecondary,
  };

  const getDaysInMonth = () => {
    const today = new Date();
    const year = today.getFullYear();
    const month = today.getMonth();
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const days = [];

    for (let i = 1; i <= lastDay.getDate(); i++) {
      days.push(new Date(year, month, i));
    }

    return days;
  };

  const days = getDaysInMonth();
  const weekDays = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];
  const months = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];
  const today = new Date();

  const hasEventOnDay = (date) => {
    return upcoming.some(s => {
      const sDate = new Date(s.date);
      return sDate.toDateString() === date.toDateString();
    });
  };

  if (loading) {
    return <div style={{ padding: '40px', textAlign: 'center', color: theme.textSecondary }}>Carregando...</div>;
  }

  return (
    <div style={pageStyle}>
      <div style={headerStyle}>
        <h1 style={titleStyle}>📊 Dashboard</h1>
        <p style={subtitleStyle}>Visão geral do sistema de escalas</p>
      </div>

      <div style={statsGridStyle}>
        {statCards.map((stat, index) => (
          <Link key={index} to={stat.path} style={{ textDecoration: 'none' }}>
            <Card style={statCardStyle} hoverable>
              <div style={iconContainerStyle(stat.color)}>{stat.icon}</div>
              <div style={statInfoStyle}>
                <span style={statLabelStyle}>{stat.label}</span>
                <span style={statValueStyle}>{stat.value}</span>
              </div>
            </Card>
          </Link>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 350px', gap: '20px' }}>
        <div>
          <h2 style={sectionTitleStyle}>📅 {months[today.getMonth()]} {today.getFullYear()}</h2>
          <div style={calendarContainerStyle}>
            <div style={calendarGridStyle}>
              {weekDays.map(day => (
                <div key={day} style={dayHeaderStyle}>{day}</div>
              ))}
              {days.map((day, index) => {
                const isToday = day.toDateString() === today.toDateString();
                const hasEvent = hasEventOnDay(day);
                return (
                  <div key={index} style={dayCellStyle(isToday, hasEvent)}>
                    {day.getDate()}
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        <div>
          <h2 style={sectionTitleStyle}>⏰ Próximas Escalas</h2>
          <Card>
            {upcoming.length === 0 ? (
              <div style={emptyStyle}>
                <p>Nenhuma escala agendada</p>
                <Link to="/generate">
                  <Button size="small" style={{ marginTop: '12px' }}>Gerar Escala</Button>
                </Link>
              </div>
            ) : (
              <div style={upcomingListStyle}>
                {upcoming.map((schedule, index) => {
                  const sDate = new Date(schedule.date);
                  return (
                    <div key={index} style={upcomingItemStyle}>
                      <div style={dateBoxStyle}>
                        <div style={dayStyle}>{sDate.getDate()}</div>
                        <div style={monthStyle}>{months[sDate.getMonth()].substring(0, 3)}</div>
                      </div>
                      <div style={upcomingInfoStyle}>
                        <div style={upcomingTitleStyle}>{schedule.name || 'Escala'}</div>
                        <div style={upcomingMetaStyle}>
                          {schedule.status === 'draft' ? '📝 Rascunho' : '✅ Publicada'}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </Card>

          <div style={{ marginTop: '20px' }}>
            <Link to="/generate" style={{ textDecoration: 'none' }}>
              <Button fullWidth icon="⚡">Gerar Nova Escala</Button>
            </Link>
          </div>
        </div>
      </div>

      <style>{`
        @media (max-width: 900px) {
          div[style*="grid-template-columns: 1fr 350px"] {
            grid-template-columns: 1fr !important;
          }
        }
      `}</style>
    </div>
  );
}

export default Dashboard;
